import statsmodels.api as sm
from statsmodels.tsa.holtwinters import ExponentialSmoothing
y=df['sales_units']
for trend in [None,'add','mul']:
    for seas in ['add','mul']:
        try:
            fit=ExponentialSmoothing(y, trend=trend, seasonal=seas, seasonal_periods=12, initialization_method='estimated').fit(optimized=True, use_brute=True)
            fc=fit.forecast(1).iloc[0]
            print(trend, seas, fc, fit.aic, fit.params)
        except Exception as e:
            print("err", trend,seas,e)
